// Package service holds the artifact business operations, independent of any
// HTTP framework and of any concrete storage backend. Callers register and
// query artifacts through this package and interpret the outcome without
// touching *gin.Context, http.ResponseWriter, database/sql or a specific
// database driver.
//
// Persistence is reached only through the Store interface. A caller may supply
// its own implementation; the bundled SQLite adapter lives in internal/store.
package service

import (
	"errors"
	"time"
)

// Artifact is one registration record returned to business callers. Field
// names mirror the persisted record and the published JSON contract.
type Artifact struct {
	Repository        string
	Digest            string
	Tag               string
	SignatureVerified bool
	RetentionDays     int64
	SizeBytes         int64
	PushedAt          string
}

// RegisterInput is a registration request after the caller has validated and
// normalized every field. The service adds no transport-level validation; it
// assumes non-empty repository/tag, a well-formed digest and an in-range
// retention period.
type RegisterInput struct {
	Repository        string
	Digest            string
	Tag               string
	SignatureVerified bool
	RetentionDays     int64
	SizeBytes         int64
}

// QueryKind selects how a Query is resolved.
type QueryKind int

const (
	// QueryByRepository lists every record of one repository.
	QueryByRepository QueryKind = iota
	// QueryByTag resolves a tag to its current record.
	QueryByTag
	// QueryByDigest resolves an exact (repository, digest) identity.
	QueryByDigest
)

// Query is a validated business query: repository always set; Tag or Digest
// populated only when Kind asks for them.
type Query struct {
	Kind       QueryKind
	Repository string
	Tag        string
	Digest     string
}

// RegisterOutcome distinguishes a first registration from an identical retry.
type RegisterOutcome int

const (
	// OutcomeCreated means a record was written and its tag pointer moved.
	OutcomeCreated RegisterOutcome = iota
	// OutcomeDuplicate means identical content already existed; nothing changed.
	OutcomeDuplicate
)

// Sentinel failures a business caller must be able to tell apart. They carry no
// database detail, so callers may surface them directly to their own clients.
var (
	// ErrConflict reports a (repository, digest) identity whose stored content
	// differs from the submitted content.
	ErrConflict = errors.New("artifact content conflicts with the existing record")
	// ErrNotFound reports a legal query that matched no committed record.
	ErrNotFound = errors.New("no artifact matches this query")
	// ErrStorage reports that the storage layer was not usable.
	ErrStorage = errors.New("database is not available")
)

// RegisterResult pairs the resulting record with whether it was newly written.
type RegisterResult struct {
	Artifact Artifact
	Outcome  RegisterOutcome
}

// Record is one persisted artifact as seen across the storage contract. It is
// the data shape Store implementations exchange; business callers work with
// Artifact instead. PushedAt is assigned by the service at first registration
// and never changes afterwards.
type Record struct {
	Repository        string
	Digest            string
	Tag               string
	SignatureVerified bool
	RetentionDays     int64
	SizeBytes         int64
	PushedAt          string
}

// RegisterStatus describes how a Store.Register resolution ended. It is the
// storage-level tri-state a backend must distinguish, independent of the
// business-level OutcomeCreated/OutcomeDuplicate pair.
type RegisterStatus int

const (
	// StatusCreated means the record was newly written and its tag pointer moved.
	StatusCreated RegisterStatus = iota
	// StatusDuplicate means identical content already existed; nothing was written.
	StatusDuplicate
	// StatusConflict means the (repository, digest) identity exists with different content.
	StatusConflict
)

// ErrRecordNotFound is the storage-layer miss signal. A Store returns it when a
// tag or digest lookup matches no committed row. It is deliberately distinct
// from a transport or other failure, which a Store reports as a non-nil error
// of its own, so the service never mistakes a backend fault for a miss.
var ErrRecordNotFound = errors.New("store: no matching record")

// Store is the persistence port the business layer depends on. Any backend —
// the bundled SQLite adapter or a caller-supplied implementation — may satisfy
// it with its own types; none of database/sql or the concrete driver leaks
// through this contract.
//
// Register writes the record and moves its tag pointer as one atomic
// operation. An identical re-submission returns the stored record with
// StatusDuplicate and changes nothing; different content for an existing
// (repository, digest) is StatusConflict and also changes nothing.
//
// ListRecords returns a repository's records in first-registration order.
// RecordByDigest and RecordByTag return ErrRecordNotFound on a miss and a
// different non-nil error only when the backend itself failed.
type Store interface {
	Register(record Record) (Record, RegisterStatus, error)
	ListRecords(repository string) ([]Record, error)
	RecordByDigest(repository, digest string) (Record, error)
	RecordByTag(repository, tag string) (Record, error)
}

// Service runs artifact operations against a Store.
type Service struct {
	store Store
}

// New builds a Service over the given Store.
func New(st Store) *Service {
	return &Service{store: st}
}

// Register records a validated registration. A first registration stores the
// service-generated UTC RFC3339 push time and moves the repository's tag
// pointer in the backend's single transaction. An identical retry returns the
// original record as OutcomeDuplicate without writes. Different content for an
// existing identity returns ErrConflict and changes nothing. Storage failures
// return ErrStorage.
func (s *Service) Register(input RegisterInput) (RegisterResult, error) {
	record, status, err := s.store.Register(Record{
		Repository:        input.Repository,
		Digest:            input.Digest,
		Tag:               input.Tag,
		SignatureVerified: input.SignatureVerified,
		RetentionDays:     input.RetentionDays,
		SizeBytes:         input.SizeBytes,
		PushedAt:          time.Now().UTC().Format(time.RFC3339),
	})
	if err != nil {
		return RegisterResult{}, ErrStorage
	}
	if status == StatusConflict {
		return RegisterResult{}, ErrConflict
	}
	return RegisterResult{
		Artifact: fromRecord(record),
		Outcome:  mapStatus(status),
	}, nil
}

// Query resolves a validated business query against committed state. A
// repository list returns records in first-registration order; tag and digest
// lookups return the single matching record. No match is ErrNotFound; storage
// trouble is ErrStorage and is never mistaken for a miss.
func (s *Service) Query(q Query) ([]Artifact, error) {
	var (
		records []Record
		err     error
	)
	switch q.Kind {
	case QueryByTag:
		var record Record
		record, err = s.store.RecordByTag(q.Repository, q.Tag)
		if err == nil {
			records = []Record{record}
		}
	case QueryByDigest:
		var record Record
		record, err = s.store.RecordByDigest(q.Repository, q.Digest)
		if err == nil {
			records = []Record{record}
		}
	default:
		records, err = s.store.ListRecords(q.Repository)
	}

	switch {
	case errors.Is(err, ErrRecordNotFound):
		return nil, ErrNotFound
	case err != nil:
		return nil, ErrStorage
	case len(records) == 0:
		return nil, ErrNotFound
	default:
		return fromRecordList(records), nil
	}
}

func mapStatus(status RegisterStatus) RegisterOutcome {
	if status == StatusDuplicate {
		return OutcomeDuplicate
	}
	return OutcomeCreated
}

func fromRecord(r Record) Artifact {
	return Artifact{
		Repository:        r.Repository,
		Digest:            r.Digest,
		Tag:               r.Tag,
		SignatureVerified: r.SignatureVerified,
		RetentionDays:     r.RetentionDays,
		SizeBytes:         r.SizeBytes,
		PushedAt:          r.PushedAt,
	}
}

func fromRecordList(records []Record) []Artifact {
	out := make([]Artifact, len(records))
	for i, record := range records {
		out[i] = fromRecord(record)
	}
	return out
}

package api

import (
	"errors"
	"net/http"

	"github.com/gin-gonic/gin"

	"github.com/Bob-xisuke/orb-registry-catalog/internal/input"
	"github.com/Bob-xisuke/orb-registry-catalog/internal/service"
)

const (
	codeInvalidInput = "InvalidArtifactInputError"
	codeConflict     = "ArtifactConflictError"
	codeNotFound     = "ArtifactNotFoundError"
	codeStorage      = "storage_unavailable"
)

func writeError(c *gin.Context, status int, code, message string) {
	c.JSON(status, gin.H{"error": gin.H{"code": code, "message": message}})
}

func artifactResponse(a service.Artifact) gin.H {
	return gin.H{
		"repository":         a.Repository,
		"digest":             a.Digest,
		"tag":                a.Tag,
		"signature_verified": a.SignatureVerified,
		"retention_days":     a.RetentionDays,
		"size_bytes":         a.SizeBytes,
		"pushed_at":          a.PushedAt,
	}
}

func registerArtifact(svc *service.Service) gin.HandlerFunc {
	return func(c *gin.Context) {
		// The request body is parsed and validated by the shared,
		// framework-free input entry; the handler never inspects JSON itself.
		in, err := input.ParseRegistration(c.Request.Body)
		if err != nil {
			writeError(c, http.StatusBadRequest, codeInvalidInput, "request body is not a valid artifact registration")
			return
		}

		result, err := svc.Register(in)
		switch {
		case errors.Is(err, service.ErrConflict):
			writeError(c, http.StatusConflict, codeConflict, "an artifact with this repository and digest already exists with different content")
		case err != nil:
			writeError(c, http.StatusServiceUnavailable, codeStorage, "database is not available")
		default:
			// First registrations and identical retries share the public 201;
			// the created/duplicate distinction stays inside the service result.
			c.JSON(http.StatusCreated, artifactResponse(result.Artifact))
		}
	}
}

func queryArtifacts(svc *service.Service) gin.HandlerFunc {
	return func(c *gin.Context) {
		// The raw query string (without '?') goes through the same shared
		// entry a direct caller uses; the handler only dispatches its result.
		query, err := input.ParseQuery(c.Request.URL.RawQuery)
		if err != nil {
			writeError(c, http.StatusBadRequest, codeInvalidInput, "query parameters are not valid")
			return
		}

		artifacts, err := svc.Query(query)
		switch {
		case errors.Is(err, service.ErrNotFound):
			writeError(c, http.StatusNotFound, codeNotFound, "no artifact matches this query")
		case err != nil:
			writeError(c, http.StatusServiceUnavailable, codeStorage, "database is not available")
		default:
			response := make([]gin.H, 0, len(artifacts))
			for _, record := range artifacts {
				response = append(response, artifactResponse(record))
			}
			c.JSON(http.StatusOK, gin.H{"artifacts": response})
		}
	}
}

package api

// These regression cases pin the visibility of the bundled SQLite adapter's
// registration transaction while it is still open and after it rolls back.
// They run against a real SQLite file (no in-memory stand-in and no fake
// store): the production *store.Store serves every HTTP request, and a second
// database/sql connection to the same file acts only as a test harness that
// holds a registration-shaped transaction open or installs a trigger that
// makes the tag-pointer update fail. Every observable result is asserted
// through the public HTTP surface; the harness never reads results back.
//
// The visibility conclusions belong to the bundled SQLite adapter only. A
// caller-supplied service.Store provides the same guarantees solely through
// its own implementation.

import (
	"database/sql"
	"net/http"
	"path/filepath"
	"strings"
	"testing"
	"time"

	"github.com/gin-gonic/gin"

	"github.com/Bob-xisuke/orb-registry-catalog/internal/store"
	_ "modernc.org/sqlite"
)

// newVisibilityRouter opens a real SQLite file, wires the production router
// onto it, and returns a second independent connection pool to the same file
// for fault injection. Both handles are closed by test cleanup.
func newVisibilityRouter(t *testing.T) (*gin.Engine, *sql.DB) {
	t.Helper()
	path := filepath.Join(t.TempDir(), "service.db")
	st, err := store.Open(path)
	if err != nil {
		t.Fatalf("open store: %v", err)
	}
	t.Cleanup(func() { st.Close() })

	harness, err := sql.Open("sqlite", path)
	if err != nil {
		t.Fatalf("open harness connection: %v", err)
	}
	t.Cleanup(func() { harness.Close() })
	return NewRouter(st), harness
}

// waitForPendingWriteLock proves, from outside the open transaction, that the
// writer connection currently holds SQLite's single writer lock. A no-op
// autocommit write issued on another connection must fail "database is
// locked"; once that has been observed the pending transaction is live across
// connections, so the HTTP reads that follow genuinely race an in-flight
// registration rather than a finished one.
func waitForPendingWriteLock(t *testing.T, db *sql.DB) {
	t.Helper()
	deadline := time.Now().Add(2 * time.Second)
	for {
		_, err := db.Exec(`UPDATE service_metadata SET value = value WHERE key = 'visibility-probe'`)
		if err != nil && strings.Contains(strings.ToLower(err.Error()), "locked") {
			return
		}
		if time.Now().After(deadline) {
			t.Fatalf("open transaction never held the SQLite writer lock (last probe error: %v)", err)
		}
		time.Sleep(time.Millisecond)
	}
}

// TestSQLiteUncommittedRegistrationIsInvisible registers A through the public
// entry, then holds B's record insert and tag-pointer move inside an
// uncommitted transaction mirroring store.go:66-77. Until commit, every query
// kind must answer as if B did not exist and A's record were untouched; after
// commit, fresh independent queries observe B atomically, in first-
// registration order, and retrying A still returns A's original record while
// the tag stays on B.
func TestSQLiteUncommittedRegistrationIsInvisible(t *testing.T) {
	router, harness := newVisibilityRouter(t)

	// Phase 0: A is registered and committed through POST /v1/artifacts.
	first := postArtifact(t, router,
		registration(sequenceRepo, testDigestA, sequenceTag, true, regRetention, regSizeA))
	if first.Code != http.StatusCreated {
		t.Fatalf("register A status = %d, want %d (%s)", first.Code, http.StatusCreated, first.Body)
	}
	recordA := decodeBody(t, first)
	pushedA := recordA["pushed_at"].(string)

	// Phase 1: a second connection performs the exact two writes from
	// Store.Register's created branch (store.go:66-77) but stops short of the
	// Commit at store.go:78. B's row and the tag move are both pending.
	tx, err := harness.Begin()
	if err != nil {
		t.Fatalf("harness begin: %v", err)
	}
	pushedB := time.Now().UTC().Format(time.RFC3339)
	if _, err := tx.Exec(
		`INSERT INTO artifacts (repository, digest, tag, signature_verified, retention_days, size_bytes, pushed_at)
		 VALUES (?, ?, ?, ?, ?, ?, ?)`,
		sequenceRepo, testDigestB, sequenceTag, 1, regRetention, regSizeB, pushedB); err != nil {
		t.Fatalf("harness insert B: %v", err)
	}
	if _, err := tx.Exec(
		`INSERT INTO tag_pointers (repository, tag, digest) VALUES (?, ?, ?)
		 ON CONFLICT (repository, tag) DO UPDATE SET digest = excluded.digest`,
		sequenceRepo, sequenceTag, testDigestB); err != nil {
		t.Fatalf("harness move tag pointer: %v", err)
	}
	waitForPendingWriteLock(t, harness)

	// While the transaction is open the repository list is 200 with only A.
	preCommitList := queryList(t, router, sequenceRepo)
	if preCommitList.Code != http.StatusOK {
		t.Fatalf("list during open transaction status = %d (%s)", preCommitList.Code, preCommitList.Body)
	}
	if digests := recordDigests(allRecords(t, preCommitList)); len(digests) != 1 || digests[0] != testDigestA {
		t.Fatalf("list during open transaction = %v, want [A] only", digests)
	}

	// The tag still resolves to committed A with A's original pushed_at.
	tagged := soleRecord(t, queryByTag(t, router, sequenceRepo, sequenceTag))
	if tagged["digest"] != testDigestA || tagged["pushed_at"] != pushedA {
		t.Fatalf("tag during open transaction = %v, want committed A (%s)", tagged, pushedA)
	}

	// A's record is byte-for-byte the first registration at every phase.
	expectStoredRecord(t, soleRecord(t, queryByDigest(t, router, sequenceRepo, testDigestA)),
		sequenceRepo, testDigestA, sequenceTag, true,
		float64(regRetention), float64(regSizeA), pushedA)

	// B's digest is a legal identity that simply matches no committed record.
	assertErrorResponse(t, queryByDigest(t, router, sequenceRepo, testDigestB),
		http.StatusNotFound, codeNotFound, msgNotFound)

	// Phase 2: the registration transaction commits. Fresh independent queries
	// now observe both changes together: record visible and pointer moved.
	if err := tx.Commit(); err != nil {
		t.Fatalf("harness commit: %v", err)
	}

	records := allRecords(t, queryList(t, router, sequenceRepo))
	if digests := recordDigests(records); len(digests) != 2 ||
		digests[0] != testDigestA || digests[1] != testDigestB {
		t.Fatalf("list after commit = %v, want [A B] in first-registration order", digests)
	}
	if records[0].(map[string]any)["pushed_at"] != pushedA {
		t.Fatalf("A record changed when B committed: %v", records[0])
	}

	pointedB := soleRecord(t, queryByTag(t, router, sequenceRepo, sequenceTag))
	expectStoredRecord(t, pointedB, sequenceRepo, testDigestB, sequenceTag, true,
		float64(regRetention), float64(regSizeB), pushedB)

	expectStoredRecord(t, soleRecord(t, queryByDigest(t, router, sequenceRepo, testDigestA)),
		sequenceRepo, testDigestA, sequenceTag, true,
		float64(regRetention), float64(regSizeA), pushedA)
	expectStoredRecord(t, soleRecord(t, queryByDigest(t, router, sequenceRepo, testDigestB)),
		sequenceRepo, testDigestB, sequenceTag, true,
		float64(regRetention), float64(regSizeB), pushedB)

	// Cross-request boundary: the list response captured BEFORE commit contains
	// only A, while a SEPARATE tag query issued AFTER commit hits B. Each query
	// is its own autocommit read; nothing promises one snapshot spanning the two
	// requests, so this pairing is a legal result rather than a contradiction.
	if digests := recordDigests(allRecords(t, preCommitList)); len(digests) != 1 || digests[0] != testDigestA {
		t.Fatalf("earlier list response changed after commit: %v", digests)
	}
	if laterTag := soleRecord(t, queryByTag(t, router, sequenceRepo, sequenceTag)); laterTag["digest"] != testDigestB {
		t.Fatalf("later tag query = %v, want committed B", laterTag["digest"])
	}

	// Phase 3: after B commits, retrying A verbatim is still 201 with A's
	// original record (pushed_at included) and never moves the pointer back.
	retry := postArtifact(t, router,
		registration(sequenceRepo, testDigestA, sequenceTag, true, regRetention, regSizeA))
	if retry.Code != http.StatusCreated {
		t.Fatalf("retry A after B committed status = %d, want %d (%s)", retry.Code, http.StatusCreated, retry.Body)
	}
	expectStoredRecord(t, decodeBody(t, retry), sequenceRepo, testDigestA, sequenceTag, true,
		float64(regRetention), float64(regSizeA), pushedA)
	if got := soleRecord(t, queryByTag(t, router, sequenceRepo, sequenceTag)); got["digest"] != testDigestB {
		t.Fatalf("retrying A moved the tag pointer to %v, want B", got["digest"])
	}
	if digests := recordDigests(allRecords(t, queryList(t, router, sequenceRepo))); len(digests) != 2 ||
		digests[0] != testDigestA || digests[1] != testDigestB {
		t.Fatalf("list after retry = %v, want unchanged [A B]", digests)
	}
}

// TestSQLiteRolledBackRegistrationIsInvisible models "B's row is written but
// the tag-pointer update fails". A test-only trigger rejects the upsert's
// UPDATE path, so the genuine POST /v1/artifacts request runs Store.Register's
// real failure branch: insert succeeds, tag move errors, defer tx.Rollback()
// (store.go:59) undoes the insert, and the client receives 503
// storage_unavailable. After the rollback only committed A must remain
// visible; once the trigger is dropped, the same B registers normally, which
// proves the connection pool and schema are still usable.
func TestSQLiteRolledBackRegistrationIsInvisible(t *testing.T) {
	router, harness := newVisibilityRouter(t)

	// Phase 0: A is committed and the tag points at A.
	first := postArtifact(t, router,
		registration(sequenceRepo, testDigestA, sequenceTag, true, regRetention, regSizeA))
	if first.Code != http.StatusCreated {
		t.Fatalf("register A status = %d (%s)", first.Code, first.Body)
	}
	pushedA := decodeBody(t, first)["pushed_at"].(string)

	// Phase 1: install a trigger that aborts only the tag-pointer move. The
	// artifacts insert is unaffected, so Register reaches "row written, tag
	// update failed" exactly as the failure scenario describes.
	if _, err := harness.Exec(`
		CREATE TRIGGER fail_tag_move BEFORE UPDATE ON tag_pointers
		BEGIN
			SELECT RAISE(ABORT, 'injected tag pointer update failure');
		END`); err != nil {
		t.Fatalf("create trigger: %v", err)
	}

	// Phase 2: the real registration request fails inside its transaction and
	// answers the fixed 503 shape; the injected SQL text never reaches the body.
	failed := postArtifact(t, router,
		registration(sequenceRepo, testDigestB, sequenceTag, true, regRetention, regSizeB))
	assertErrorResponse(t, failed, http.StatusServiceUnavailable, codeStorage, msgStorage)

	// Phase 3: the rolled-back transaction is indistinguishable from nothing:
	// the list still holds only A, the pointer still resolves to A with A's
	// pushed_at, A's record is intact, and B's digest misses with 404.
	if digests := recordDigests(allRecords(t, queryList(t, router, sequenceRepo))); len(digests) != 1 ||
		digests[0] != testDigestA {
		t.Fatalf("list after rollback = %v, want [A] only", digests)
	}
	tagged := soleRecord(t, queryByTag(t, router, sequenceRepo, sequenceTag))
	if tagged["digest"] != testDigestA || tagged["pushed_at"] != pushedA {
		t.Fatalf("tag after rollback = %v, want committed A (%s)", tagged, pushedA)
	}
	expectStoredRecord(t, soleRecord(t, queryByDigest(t, router, sequenceRepo, testDigestA)),
		sequenceRepo, testDigestA, sequenceTag, true,
		float64(regRetention), float64(regSizeA), pushedA)
	assertErrorResponse(t, queryByDigest(t, router, sequenceRepo, testDigestB),
		http.StatusNotFound, codeNotFound, msgNotFound)

	// Phase 4: remove the injected fault and register B again. The store is
	// fully usable post-rollback: B commits, the order is [A B] and the tag
	// moves to B.
	if _, err := harness.Exec(`DROP TRIGGER fail_tag_move`); err != nil {
		t.Fatalf("drop trigger: %v", err)
	}
	recovered := postArtifact(t, router,
		registration(sequenceRepo, testDigestB, sequenceTag, true, regRetention, regSizeB))
	if recovered.Code != http.StatusCreated {
		t.Fatalf("register B after recovery status = %d, want %d (%s)",
			recovered.Code, http.StatusCreated, recovered.Body)
	}
	if digests := recordDigests(allRecords(t, queryList(t, router, sequenceRepo))); len(digests) != 2 ||
		digests[0] != testDigestA || digests[1] != testDigestB {
		t.Fatalf("list after recovery = %v, want [A B]", digests)
	}
	if got := soleRecord(t, queryByTag(t, router, sequenceRepo, sequenceTag)); got["digest"] != testDigestB {
		t.Fatalf("tag after recovery = %v, want B", got["digest"])
	}
}

// Package store is the SQLite-backed adapter for the service.Store port. It
// owns the SQLite file and every write the service performs, but defines no
// business data types of its own: records, register statuses and the
// not-found sentinel all come from the service storage contract.
package store

import (
	"database/sql"
	"errors"
	"fmt"

	"github.com/Bob-xisuke/orb-registry-catalog/internal/service"

	_ "modernc.org/sqlite"
)

// Compile-time assertion that *Store is a service.Store.
var _ service.Store = (*Store)(nil)

// Store wraps the SQLite handle so callers never touch database/sql directly.
type Store struct {
	db *sql.DB
}

// Open prepares the database file and the schema this service needs.
func Open(path string) (*Store, error) {
	db, err := sql.Open("sqlite", path)
	if err != nil {
		return nil, fmt.Errorf("open sqlite: %w", err)
	}
	if _, err := db.Exec("PRAGMA journal_mode=WAL"); err != nil {
		db.Close()
		return nil, fmt.Errorf("enable wal: %w", err)
	}
	if _, err := db.Exec(schema); err != nil {
		db.Close()
		return nil, fmt.Errorf("apply schema: %w", err)
	}
	return &Store{db: db}, nil
}

// Ping reports whether the storage layer is usable.
func (s *Store) Ping() error { return s.db.Ping() }

// Close releases the database handle.
func (s *Store) Close() error { return s.db.Close() }

const recordColumns = `repository, digest, tag, signature_verified, retention_days, size_bytes, pushed_at`

// Register writes a new artifact and moves its tag pointer in a single
// transaction, so readers only ever see both changes or neither. Re-submitting
// identical content returns the stored record without moving the tag pointer;
// different content for an existing (repository, digest) is a conflict.
func (s *Store) Register(a service.Record) (service.Record, service.RegisterStatus, error) {
	tx, err := s.db.Begin()
	if err != nil {
		return service.Record{}, 0, fmt.Errorf("begin register: %w", err)
	}
	defer tx.Rollback()

	existing, err := scanRecord(tx.QueryRow(
		`SELECT `+recordColumns+` FROM artifacts WHERE repository = ? AND digest = ?`,
		a.Repository, a.Digest))
	switch {
	case errors.Is(err, service.ErrRecordNotFound):
		if _, err := tx.Exec(
			`INSERT INTO artifacts (`+recordColumns+`) VALUES (?, ?, ?, ?, ?, ?, ?)`,
			a.Repository, a.Digest, a.Tag, a.SignatureVerified,
			a.RetentionDays, a.SizeBytes, a.PushedAt); err != nil {
			return service.Record{}, 0, fmt.Errorf("insert artifact: %w", err)
		}
		if _, err := tx.Exec(
			`INSERT INTO tag_pointers (repository, tag, digest) VALUES (?, ?, ?)
			 ON CONFLICT (repository, tag) DO UPDATE SET digest = excluded.digest`,
			a.Repository, a.Tag, a.Digest); err != nil {
			return service.Record{}, 0, fmt.Errorf("move tag pointer: %w", err)
		}
		if err := tx.Commit(); err != nil {
			return service.Record{}, 0, fmt.Errorf("commit register: %w", err)
		}
		return a, service.StatusCreated, nil
	case err != nil:
		return service.Record{}, 0, fmt.Errorf("lookup artifact: %w", err)
	}

	if existing.Tag == a.Tag &&
		existing.SignatureVerified == a.SignatureVerified &&
		existing.RetentionDays == a.RetentionDays &&
		existing.SizeBytes == a.SizeBytes {
		return existing, service.StatusDuplicate, nil
	}
	return service.Record{}, service.StatusConflict, nil
}

// ListRecords returns every record for a repository in first-registration order.
func (s *Store) ListRecords(repository string) ([]service.Record, error) {
	rows, err := s.db.Query(
		`SELECT `+recordColumns+` FROM artifacts WHERE repository = ? ORDER BY id`, repository)
	if err != nil {
		return nil, fmt.Errorf("list artifacts: %w", err)
	}
	defer rows.Close()

	var out []service.Record
	for rows.Next() {
		var a service.Record
		if err := rows.Scan(&a.Repository, &a.Digest, &a.Tag, &a.SignatureVerified,
			&a.RetentionDays, &a.SizeBytes, &a.PushedAt); err != nil {
			return nil, fmt.Errorf("scan artifact: %w", err)
		}
		out = append(out, a)
	}
	if err := rows.Err(); err != nil {
		return nil, fmt.Errorf("list artifacts: %w", err)
	}
	return out, nil
}

// RecordByDigest returns the record for an exact (repository, digest) identity.
func (s *Store) RecordByDigest(repository, digest string) (service.Record, error) {
	return scanRecord(s.db.QueryRow(
		`SELECT `+recordColumns+` FROM artifacts WHERE repository = ? AND digest = ?`,
		repository, digest))
}

// RecordByTag resolves the current tag pointer to the record it references.
func (s *Store) RecordByTag(repository, tag string) (service.Record, error) {
	return scanRecord(s.db.QueryRow(
		`SELECT a.repository, a.digest, a.tag, a.signature_verified,
		        a.retention_days, a.size_bytes, a.pushed_at
		 FROM tag_pointers p
		 JOIN artifacts a ON a.repository = p.repository AND a.digest = p.digest
		 WHERE p.repository = ? AND p.tag = ?`, repository, tag))
}

func scanRecord(row *sql.Row) (service.Record, error) {
	var a service.Record
	if err := row.Scan(&a.Repository, &a.Digest, &a.Tag, &a.SignatureVerified,
		&a.RetentionDays, &a.SizeBytes, &a.PushedAt); err != nil {
		if errors.Is(err, sql.ErrNoRows) {
			return service.Record{}, service.ErrRecordNotFound
		}
		return service.Record{}, err
	}
	return a, nil
}

const schema = `
CREATE TABLE IF NOT EXISTS service_metadata (
	key   TEXT PRIMARY KEY,
	value TEXT NOT NULL
);
CREATE TABLE IF NOT EXISTS artifacts (
	id                 INTEGER PRIMARY KEY AUTOINCREMENT,
	repository         TEXT NOT NULL,
	digest             TEXT NOT NULL,
	tag                TEXT NOT NULL,
	signature_verified INTEGER NOT NULL,
	retention_days     INTEGER NOT NULL,
	size_bytes         INTEGER NOT NULL,
	pushed_at          TEXT NOT NULL,
	UNIQUE (repository, digest)
);
CREATE TABLE IF NOT EXISTS tag_pointers (
	repository TEXT NOT NULL,
	tag        TEXT NOT NULL,
	digest     TEXT NOT NULL,
	PRIMARY KEY (repository, tag)
);
`

package api

import (
	"net/http"

	"github.com/gin-gonic/gin"

	"github.com/Bob-xisuke/orb-registry-catalog/internal/service"
	"github.com/Bob-xisuke/orb-registry-catalog/internal/store"
)

// HealthCheck is the caller-supplied probe behind GET /healthz. It is invoked
// on every health request and its result alone decides the response: nil
// error keeps the published 200 body, any error the published 503. Artifact
// registration and queries never consult it.
type HealthCheck func() error

// NewRouter keeps the original SQLite-backed assembly for existing callers:
// the bundled store serves the storage contract and its own Ping becomes the
// health check.
func NewRouter(st *store.Store) *gin.Engine {
	return NewRouterWithStore(st, st.Ping)
}

// NewRouterWithStore wires the public HTTP surface around any service.Store
// plus an independent health check. The store may be a caller-supplied
// implementation of the storage contract; it needs no Ping method, no SQLite
// and no database/sql. The router never opens a database itself and never
// closes the store it is given: ownership and lifecycle stay with the caller.
// A nil health check reports the service as healthy. The service contract in
// README.md describes the error shape every entry must keep.
func NewRouterWithStore(st service.Store, health HealthCheck) *gin.Engine {
	gin.SetMode(gin.ReleaseMode)
	router := gin.New()
	router.Use(gin.Recovery())

	svc := service.New(st)

	router.GET("/healthz", func(c *gin.Context) {
		if health != nil && health() != nil {
			c.JSON(http.StatusServiceUnavailable, gin.H{"error": gin.H{"code": codeStorage, "message": "database is not available"}})
			return
		}
		c.JSON(http.StatusOK, gin.H{"status": "ok", "database": "ok"})
	})

	router.POST("/v1/artifacts", registerArtifact(svc))
	router.GET("/v1/artifacts", queryArtifacts(svc))

	router.NoRoute(func(c *gin.Context) {
		c.JSON(http.StatusNotFound, gin.H{"error": gin.H{"code": "route_not_found", "message": "no route matches this path"}})
	})
	return router
}

package api

// These regression cases exercise only the public HTTP surface
// (POST/GET /v1/artifacts, GET /healthz) and back the conclusions in
// docs/artifact-identity-analysis.md. They deliberately avoid the store's
// unexported internals so that any refactor preserving the published contract
// keeps them green.

import (
	"fmt"
	"net/http"
	"net/http/httptest"
	"path/filepath"
	"strings"
	"testing"

	"github.com/gin-gonic/gin"

	"github.com/Bob-xisuke/orb-registry-catalog/internal/store"
)

const (
	sequenceRepo    = "registry-demo/control"
	otherRepoOne    = "registry-demo/one"
	otherRepoTwo    = "registry-demo/two"
	sequenceTag     = "release"
	regRetention    = int64(30)
	regSizeA        = int64(1024)
	regSizeB        = int64(2048)
	msgInvalidReg   = "request body is not a valid artifact registration"
	msgInvalidQuery = "query parameters are not valid"
	msgConflict     = "an artifact with this repository and digest already exists with different content"
	msgNotFound     = "no artifact matches this query"
	msgStorage      = "database is not available"
)

func registration(repo, digest, tag string, sig bool, retention, size int64) string {
	return fmt.Sprintf(
		`{"repository":%q,"digest":%q,"tag":%q,"signature_verified":%t,"retention_days":%d,"size_bytes":%d}`,
		repo, digest, tag, sig, retention, size)
}

func allRecords(t *testing.T, recorder *httptest.ResponseRecorder) []any {
	t.Helper()
	items, ok := decodeBody(t, recorder)["artifacts"].([]any)
	if !ok {
		t.Fatalf("response has no artifacts array: %s", recorder.Body)
	}
	return items
}

func soleRecord(t *testing.T, recorder *httptest.ResponseRecorder) map[string]any {
	t.Helper()
	items := allRecords(t, recorder)
	if len(items) != 1 {
		t.Fatalf("got %d records, want exactly 1: %s", len(items), recorder.Body)
	}
	return items[0].(map[string]any)
}

func recordDigests(records []any) []string {
	out := make([]string, len(records))
	for i, record := range records {
		out[i] = record.(map[string]any)["digest"].(string)
	}
	return out
}

// assertErrorResponse pins the published error contract: one top-level error
// object holding exactly the two string fields code and message, and the
// message must never carry SQL, stack frames or filesystem paths.
func assertErrorResponse(t *testing.T, recorder *httptest.ResponseRecorder, wantStatus int, wantCode, wantMessage string) {
	t.Helper()
	if recorder.Code != wantStatus {
		t.Fatalf("status = %d, want %d (%s)", recorder.Code, wantStatus, recorder.Body)
	}
	errObj, ok := decodeBody(t, recorder)["error"].(map[string]any)
	if !ok {
		t.Fatalf("response has no error object: %s", recorder.Body)
	}
	if code, _ := errObj["code"].(string); code != wantCode {
		t.Fatalf("error code = %q, want %q", code, wantCode)
	}
	message, ok := errObj["message"].(string)
	if !ok || message != wantMessage {
		t.Fatalf("error message = %v, want %q", errObj["message"], wantMessage)
	}
	if len(errObj) != 2 {
		t.Fatalf("error object has unexpected fields: %v", errObj)
	}
	lowered := strings.ToLower(message)
	for _, leaked := range []string{"sql", "sqlite", "insert", "select", "begin", ".go", "/", "goroutine", "stack"} {
		if strings.Contains(lowered, leaked) {
			t.Fatalf("error message %q leaks internal detail %q", message, leaked)
		}
	}
}

// expectStoredRecord compares every field of a record returned by the API.
func expectStoredRecord(t *testing.T, record map[string]any, repo, digest, tag string, sig bool, retention, size float64, pushedAt string) {
	t.Helper()
	want := map[string]any{
		"repository":         repo,
		"digest":             digest,
		"tag":                tag,
		"signature_verified": sig,
		"retention_days":     retention,
		"size_bytes":         size,
		"pushed_at":          pushedAt,
	}
	for key, value := range want {
		if record[key] != value {
			t.Fatalf("field %s = %v, want %v (record %v)", key, record[key], value, record)
		}
	}
}

func queryByTag(t *testing.T, router *gin.Engine, repo, tag string) *httptest.ResponseRecorder {
	t.Helper()
	return getArtifacts(t, router, "repository="+repo+"&tag="+tag)
}

func queryByDigest(t *testing.T, router *gin.Engine, repo, digest string) *httptest.ResponseRecorder {
	t.Helper()
	return getArtifacts(t, router, "repository="+repo+"&digest="+digest)
}

func queryList(t *testing.T, router *gin.Engine, repo string) *httptest.ResponseRecorder {
	t.Helper()
	return getArtifacts(t, router, "repository="+repo)
}

// TestRegistrationSequenceIdentityAndTagPointer walks the full scenario:
// register A, register B under the same tag, retry A verbatim, then mutate each
// comparable field of A. The immutable registration record and the mutable tag
// pointer must stay distinguishable at every step.
func TestRegistrationSequenceIdentityAndTagPointer(t *testing.T) {
	router, _ := newTestRouter(t)

	bodyA := registration(sequenceRepo, testDigestA, sequenceTag, true, regRetention, regSizeA)
	bodyB := registration(sequenceRepo, testDigestB, sequenceTag, true, regRetention, regSizeB)

	// 1. First registration of A: 201 with the service-generated pushed_at.
	first := postArtifact(t, router, bodyA)
	if first.Code != http.StatusCreated {
		t.Fatalf("register A status = %d, want %d (%s)", first.Code, http.StatusCreated, first.Body)
	}
	recordA := decodeBody(t, first)
	pushedA, _ := recordA["pushed_at"].(string)
	if pushedA == "" {
		t.Fatalf("A response has no pushed_at: %v", recordA)
	}
	expectStoredRecord(t, recordA, sequenceRepo, testDigestA, sequenceTag, true,
		float64(regRetention), float64(regSizeA), pushedA)

	// Independent query before B is registered: the tag points at A and reads
	// only committed state.
	if got := soleRecord(t, queryByTag(t, router, sequenceRepo, sequenceTag)); got["digest"] != testDigestA {
		t.Fatalf("tag before B points at %v, want %s", got["digest"], testDigestA)
	}

	// 2. Register B with the same tag: 201, tag pointer moves to B, A survives.
	second := postArtifact(t, router, bodyB)
	if second.Code != http.StatusCreated {
		t.Fatalf("register B status = %d, want %d (%s)", second.Code, http.StatusCreated, second.Body)
	}
	recordB := decodeBody(t, second)
	pushedB, _ := recordB["pushed_at"].(string)
	expectStoredRecord(t, recordB, sequenceRepo, testDigestB, sequenceTag, true,
		float64(regRetention), float64(regSizeB), pushedB)

	// A second, independent query now observes the committed pointer move.
	if got := soleRecord(t, queryByTag(t, router, sequenceRepo, sequenceTag)); got["digest"] != testDigestB {
		t.Fatalf("tag after B points at %v, want %s", got["digest"], testDigestB)
	}

	// 3. Retry A verbatim: still 201, but it is the original record: the same
	// pushed_at and the pointer does not move back.
	retry := postArtifact(t, router, bodyA)
	if retry.Code != http.StatusCreated {
		t.Fatalf("retry A status = %d, want %d (%s)", retry.Code, http.StatusCreated, retry.Body)
	}
	retryRecord := decodeBody(t, retry)
	if retryRecord["pushed_at"] != pushedA {
		t.Fatalf("retry returned pushed_at %v, want original %v", retryRecord["pushed_at"], pushedA)
	}
	expectStoredRecord(t, retryRecord, sequenceRepo, testDigestA, sequenceTag, true,
		float64(regRetention), float64(regSizeA), pushedA)

	// 4. Equivalent retry after whitespace normalization, plus an unknown field:
	// still the same identity, still the original pushed_at.
	normalized := `{"repository":" ` + sequenceRepo + ` ","digest":"` + testDigestA +
		`","tag":" ` + sequenceTag + ` ","signature_verified":true,` +
		`"retention_days":30,"size_bytes":1024,"unexpected":"ignored"}`
	normRetry := postArtifact(t, router, normalized)
	if normRetry.Code != http.StatusCreated {
		t.Fatalf("normalized retry status = %d, want %d (%s)", normRetry.Code, http.StatusCreated, normRetry.Body)
	}
	if got := decodeBody(t, normRetry)["pushed_at"]; got != pushedA {
		t.Fatalf("normalized retry pushed_at = %v, want %v", got, pushedA)
	}

	// Repository list: exactly two records in first-registration order.
	records := allRecords(t, queryList(t, router, sequenceRepo))
	if digests := recordDigests(records); len(digests) != 2 ||
		digests[0] != testDigestA || digests[1] != testDigestB {
		t.Fatalf("list = %v, want [%s %s] in registration order", digests, testDigestA, testDigestB)
	}

	// Digest lookup still fetches the original A record.
	expectStoredRecord(t, soleRecord(t, queryByDigest(t, router, sequenceRepo, testDigestA)),
		sequenceRepo, testDigestA, sequenceTag, true,
		float64(regRetention), float64(regSizeA), pushedA)

	// 5. Each comparable field changed in isolation is a 409 conflict, and
	// neither the immutable record nor the tag pointer may change afterwards.
	conflicts := map[string]string{
		"changed tag":       registration(sequenceRepo, testDigestA, "other", true, regRetention, regSizeA),
		"changed signature": registration(sequenceRepo, testDigestA, sequenceTag, false, regRetention, regSizeA),
		"changed retention": registration(sequenceRepo, testDigestA, sequenceTag, true, regRetention+1, regSizeA),
		"changed size":      registration(sequenceRepo, testDigestA, sequenceTag, true, regRetention, regSizeB),
	}
	for name, body := range conflicts {
		t.Run(name, func(t *testing.T) {
			assertErrorResponse(t, postArtifact(t, router, body),
				http.StatusConflict, codeConflict, msgConflict)

			// Original A record is byte-for-byte the same through the API.
			expectStoredRecord(t, soleRecord(t, queryByDigest(t, router, sequenceRepo, testDigestA)),
				sequenceRepo, testDigestA, sequenceTag, true,
				float64(regRetention), float64(regSizeA), pushedA)

			// Tag pointer still resolves to B; the rejected request wrote nothing.
			if got := soleRecord(t, queryByTag(t, router, sequenceRepo, sequenceTag)); got["digest"] != testDigestB {
				t.Fatalf("tag pointer moved after conflict: %v, want %s", got["digest"], testDigestB)
			}
			pointed := soleRecord(t, queryByTag(t, router, sequenceRepo, sequenceTag))
			if pointed["pushed_at"] != pushedB {
				t.Fatalf("tagged record changed after conflict: %v", pointed)
			}

			// No third record appeared and registration order is unchanged.
			if digests := recordDigests(allRecords(t, queryList(t, router, sequenceRepo))); len(digests) != 2 ||
				digests[0] != testDigestA || digests[1] != testDigestB {
				t.Fatalf("list changed after conflict: %v", digests)
			}

			// The tag carried by the rejected body was never persisted.
			missing := queryByTag(t, router, sequenceRepo, "other")
			assertErrorResponse(t, missing, http.StatusNotFound, codeNotFound, msgNotFound)
		})
	}
}

// TestRepositoriesDoNotInterfere checks that the same digest and the same tag
// name in a different repository are independent identities and pointers.
func TestRepositoriesDoNotInterfere(t *testing.T) {
	router, _ := newTestRouter(t)

	first := postArtifact(t, router, registration(otherRepoOne, testDigestA, sequenceTag, true, regRetention, regSizeA))
	if first.Code != http.StatusCreated {
		t.Fatalf("repo one register status = %d (%s)", first.Code, first.Body)
	}
	second := postArtifact(t, router, registration(otherRepoTwo, testDigestA, sequenceTag, true, regRetention, regSizeA))
	if second.Code != http.StatusCreated {
		t.Fatalf("repo two register status = %d (%s)", second.Code, second.Body)
	}

	// Each repository resolves the shared tag name within its own namespace.
	if got := soleRecord(t, queryByTag(t, router, otherRepoOne, sequenceTag)); got["repository"] != otherRepoOne {
		t.Fatalf("repo one tag resolves cross-repository: %v", got)
	}
	if got := soleRecord(t, queryByTag(t, router, otherRepoTwo, sequenceTag)); got["repository"] != otherRepoTwo {
		t.Fatalf("repo two tag resolves cross-repository: %v", got)
	}

	// A conflict inside repo two must not touch repo one's record.
	crossConflict := postArtifact(t, router,
		registration(otherRepoTwo, testDigestA, sequenceTag, true, regRetention, regSizeB))
	assertErrorResponse(t, crossConflict, http.StatusConflict, codeConflict, msgConflict)
	if got := soleRecord(t, queryByDigest(t, router, otherRepoOne, testDigestA)); got["size_bytes"] != float64(regSizeA) {
		t.Fatalf("repo one record changed after repo two conflict: %v", got)
	}

	// Moving the tag in repo two (new digest B) leaves repo one's pointer at A.
	if recorder := postArtifact(t, router,
		registration(otherRepoTwo, testDigestB, sequenceTag, true, regRetention, regSizeB)); recorder.Code != http.StatusCreated {
		t.Fatalf("repo two register B status = %d (%s)", recorder.Code, recorder.Body)
	}
	if got := soleRecord(t, queryByTag(t, router, otherRepoTwo, sequenceTag)); got["digest"] != testDigestB {
		t.Fatalf("repo two tag = %v, want %s", got["digest"], testDigestB)
	}
	if got := soleRecord(t, queryByTag(t, router, otherRepoOne, sequenceTag)); got["digest"] != testDigestA {
		t.Fatalf("repo one tag = %v, want %s", got["digest"], testDigestA)
	}

	if records := allRecords(t, queryList(t, router, otherRepoOne)); len(records) != 1 {
		t.Fatalf("repo one list leaked other-repository records: %v", records)
	}
	if records := allRecords(t, queryList(t, router, otherRepoTwo)); len(records) != 2 {
		t.Fatalf("repo two list = %d records, want 2", len(records))
	}
}

// TestStorageUnavailableReturns503 closes the underlying SQLite file so every
// entry must answer 503 storage_unavailable through the public error shape.
func TestStorageUnavailableReturns503(t *testing.T) {
	path := filepath.Join(t.TempDir(), "service.db")
	st, err := store.Open(path)
	if err != nil {
		t.Fatalf("open: %v", err)
	}
	router := NewRouter(st)
	if recorder := postArtifact(t, router,
		registration(sequenceRepo, testDigestA, sequenceTag, true, regRetention, regSizeA)); recorder.Code != http.StatusCreated {
		t.Fatalf("seed register status = %d (%s)", recorder.Code, recorder.Body)
	}
	if err := st.Close(); err != nil {
		t.Fatalf("close store: %v", err)
	}

	assertErrorResponse(t,
		postArtifact(t, router, registration(sequenceRepo, testDigestB, sequenceTag, true, regRetention, regSizeB)),
		http.StatusServiceUnavailable, codeStorage, msgStorage)
	assertErrorResponse(t, queryList(t, router, sequenceRepo),
		http.StatusServiceUnavailable, codeStorage, msgStorage)
	assertErrorResponse(t, queryByTag(t, router, sequenceRepo, sequenceTag),
		http.StatusServiceUnavailable, codeStorage, msgStorage)
	assertErrorResponse(t, queryByDigest(t, router, sequenceRepo, testDigestA),
		http.StatusServiceUnavailable, codeStorage, msgStorage)

	recorder := httptest.NewRecorder()
	router.ServeHTTP(recorder, httptest.NewRequest(http.MethodGet, "/healthz", nil))
	assertErrorResponse(t, recorder, http.StatusServiceUnavailable, codeStorage, msgStorage)
}

// TestClientErrorShapeAndMessages pins the 400 and 404 messages for the query
// and registration entries; conflict messages are covered in the sequence and
// cross-repository tests above.
func TestClientErrorShapeAndMessages(t *testing.T) {
	router, _ := newTestRouter(t)
	postArtifact(t, router, registration(sequenceRepo, testDigestA, sequenceTag, true, regRetention, regSizeA))

	// Malformed registration body -> 400; decoding fails before any store write.
	assertErrorResponse(t, postArtifact(t, router, `{"repository":`),
		http.StatusBadRequest, codeInvalidInput, msgInvalidReg)

	// digest is matched by an anchored regex and is never trimmed, so leading
	// whitespace is a rejection rather than a normalization.
	assertErrorResponse(t, postArtifact(t, router,
		`{"repository":"`+sequenceRepo+`","digest":" `+testDigestA+`","tag":"`+sequenceTag+
			`","signature_verified":true,"retention_days":30,"size_bytes":1}`),
		http.StatusBadRequest, codeInvalidInput, msgInvalidReg)

	// Invalid query parameters -> 400 with the query-specific message.
	assertErrorResponse(t, getArtifacts(t, router, "tag="+sequenceTag),
		http.StatusBadRequest, codeInvalidInput, msgInvalidQuery)
	assertErrorResponse(t, getArtifacts(t, router, "repository="+sequenceRepo+"&tag="+sequenceTag+"&digest="+testDigestA),
		http.StatusBadRequest, codeInvalidInput, msgInvalidQuery)

	// Legal query with no match -> 404.
	assertErrorResponse(t, queryList(t, router, "registry-demo/missing"),
		http.StatusNotFound, codeNotFound, msgNotFound)
	assertErrorResponse(t, queryByTag(t, router, sequenceRepo, "missing-tag"),
		http.StatusNotFound, codeNotFound, msgNotFound)
	assertErrorResponse(t, queryByDigest(t, router, sequenceRepo, testDigestB),
		http.StatusNotFound, codeNotFound, msgNotFound)
}

// registrationWithField renders a valid registration body for
// registry-demo/nulls with one field replaced by the given raw JSON value, or
// omitted entirely when rawValue is empty.
func registrationWithField(field, rawValue string) string {
	values := []struct{ key, value string }{
		{"repository", `"registry-demo/nulls"`},
		{"digest", `"` + testDigestA + `"`},
		{"tag", `"release"`},
		{"signature_verified", `true`},
		{"retention_days", `30`},
		{"size_bytes", `1`},
	}
	parts := make([]string, 0, len(values))
	for _, pair := range values {
		value := pair.value
		if pair.key == field {
			if rawValue == "" {
				continue
			}
			value = rawValue
		}
		parts = append(parts, `"`+pair.key+`":`+value)
	}
	return "{" + strings.Join(parts, ",") + "}"
}

// TestRegistrationNullAndMissingRequiredFields pins the published boundary:
// every required field answers absence and an explicit JSON null with the same
// 400, while the legal zero values false and 0 remain registrable. A rejected
// body never leaves a record behind.
func TestRegistrationNullAndMissingRequiredFields(t *testing.T) {
	required := []string{"repository", "digest", "tag", "signature_verified", "retention_days", "size_bytes"}
	for _, field := range required {
		t.Run(field+" null", func(t *testing.T) {
			router, _ := newTestRouter(t)
			assertErrorResponse(t, postArtifact(t, router, registrationWithField(field, "null")),
				http.StatusBadRequest, codeInvalidInput, msgInvalidReg)
			assertErrorResponse(t, queryList(t, router, "registry-demo/nulls"),
				http.StatusNotFound, codeNotFound, msgNotFound)
		})
		t.Run(field+" missing", func(t *testing.T) {
			router, _ := newTestRouter(t)
			assertErrorResponse(t, postArtifact(t, router, registrationWithField(field, "")),
				http.StatusBadRequest, codeInvalidInput, msgInvalidReg)
			assertErrorResponse(t, queryList(t, router, "registry-demo/nulls"),
				http.StatusNotFound, codeNotFound, msgNotFound)
		})
	}

	router, _ := newTestRouter(t)

	// A legal false is not a null: it registers and reads back as false.
	unsigned := postArtifact(t, router, registrationWithField("signature_verified", "false"))
	if unsigned.Code != http.StatusCreated {
		t.Fatalf("signature_verified false status = %d (%s)", unsigned.Code, unsigned.Body)
	}
	if got := decodeBody(t, unsigned)["signature_verified"]; got != false {
		t.Fatalf("signature_verified false stored as %v", got)
	}

	// A legal zero size is not a null: it registers and reads back as 0.
	// A distinct digest keeps this a first registration rather than a conflict.
	emptyBody := strings.Replace(registrationWithField("size_bytes", "0"), testDigestA, testDigestB, 1)
	empty := postArtifact(t, router, emptyBody)
	if empty.Code != http.StatusCreated {
		t.Fatalf("size_bytes 0 status = %d (%s)", empty.Code, empty.Body)
	}
	if got := decodeBody(t, empty)["size_bytes"]; got != float64(0) {
		t.Fatalf("size_bytes 0 stored as %v", got)
	}
}

// TestRejectedRegistrationLeavesCommittedStateUntouched registers A and B
// under one tag, then submits bodies that carry A's existing identity with
// different content but are invalid (a null required field). Validation must
// answer 400 before any identity lookup — never 409 — and neither the
// committed records, their push times nor the tag pointer may change.
func TestRejectedRegistrationLeavesCommittedStateUntouched(t *testing.T) {
	router, _ := newTestRouter(t)

	first := postArtifact(t, router, registration(sequenceRepo, testDigestA, sequenceTag, true, regRetention, regSizeA))
	if first.Code != http.StatusCreated {
		t.Fatalf("register A status = %d (%s)", first.Code, first.Body)
	}
	pushedA := decodeBody(t, first)["pushed_at"].(string)
	second := postArtifact(t, router, registration(sequenceRepo, testDigestB, sequenceTag, true, regRetention, regSizeB))
	if second.Code != http.StatusCreated {
		t.Fatalf("register B status = %d (%s)", second.Code, second.Body)
	}
	pushedB := decodeBody(t, second)["pushed_at"].(string)

	// Existing (repository, digest) identity, different tag and size, but one
	// required field is null: 400 must win over the would-be 409 conflict.
	invalid := []string{
		`{"repository":"` + sequenceRepo + `","digest":"` + testDigestA + `","tag":"moved","signature_verified":true,"retention_days":30,"size_bytes":null}`,
		`{"repository":"` + sequenceRepo + `","digest":"` + testDigestA + `","tag":"moved","signature_verified":null,"retention_days":30,"size_bytes":4096}`,
	}
	for i, body := range invalid {
		assertErrorResponse(t, postArtifact(t, router, body),
			http.StatusBadRequest, codeInvalidInput, msgInvalidReg)

		// A's committed record is byte-for-byte unchanged, push time included.
		expectStoredRecord(t, soleRecord(t, queryByDigest(t, router, sequenceRepo, testDigestA)),
			sequenceRepo, testDigestA, sequenceTag, true,
			float64(regRetention), float64(regSizeA), pushedA)

		// The tag pointer still resolves to B with B's original push time.
		pointed := soleRecord(t, queryByTag(t, router, sequenceRepo, sequenceTag))
		if pointed["digest"] != testDigestB || pointed["pushed_at"] != pushedB {
			t.Fatalf("body %d moved or rewrote the tag pointer: %v", i, pointed)
		}

		// No record was added and registration order is intact.
		if digests := recordDigests(allRecords(t, queryList(t, router, sequenceRepo))); len(digests) != 2 ||
			digests[0] != testDigestA || digests[1] != testDigestB {
			t.Fatalf("body %d changed the list: %v", i, digests)
		}

		// The tag carried by the rejected body was never persisted.
		assertErrorResponse(t, queryByTag(t, router, sequenceRepo, "moved"),
			http.StatusNotFound, codeNotFound, msgNotFound)
	}
}

// TestQueryEmptyAndBareParameters pins the query boundary: only a request that
// omits tag and digest entirely lists the repository. An explicitly empty or
// valueless tag or digest is a 400, and tag plus digest is a 400 even when one
// or both values are empty — never a degraded list or single-condition query.
func TestQueryEmptyAndBareParameters(t *testing.T) {
	router, _ := newTestRouter(t)
	if recorder := postArtifact(t, router,
		registration(sequenceRepo, testDigestA, sequenceTag, true, regRetention, regSizeA)); recorder.Code != http.StatusCreated {
		t.Fatalf("seed register status = %d (%s)", recorder.Code, recorder.Body)
	}

	invalid := map[string]string{
		"tag empty value":              "repository=" + sequenceRepo + "&tag=",
		"tag bare parameter":           "repository=" + sequenceRepo + "&tag",
		"tag whitespace only":          "repository=" + sequenceRepo + "&tag=%20%20",
		"digest empty value":           "repository=" + sequenceRepo + "&digest=",
		"digest bare parameter":        "repository=" + sequenceRepo + "&digest",
		"tag and digest both empty":    "repository=" + sequenceRepo + "&tag=&digest=",
		"tag empty with valid digest":  "repository=" + sequenceRepo + "&tag=&digest=" + testDigestA,
		"digest empty with valid tag":  "repository=" + sequenceRepo + "&tag=" + sequenceTag + "&digest=",
		"repository empty value":       "repository=&tag=" + sequenceTag,
		"repository whitespace only":   "repository=%20&tag=" + sequenceTag,
		"repository bare parameter":    "repository&tag=" + sequenceTag,
		"repository omitted with tag":  "tag=" + sequenceTag,
		"repository omitted with none": "",
	}
	for name, query := range invalid {
		t.Run(name, func(t *testing.T) {
			assertErrorResponse(t, getArtifacts(t, router, query),
				http.StatusBadRequest, codeInvalidInput, msgInvalidQuery)
		})
	}

	// Omitting tag and digest lists the whole repository.
	if records := allRecords(t, queryList(t, router, sequenceRepo)); len(records) != 1 {
		t.Fatalf("repository list = %v, want the one seeded record", records)
	}

	// Legal single-condition queries still hit, and legal misses stay 404.
	if got := soleRecord(t, queryByTag(t, router, sequenceRepo, sequenceTag)); got["digest"] != testDigestA {
		t.Fatalf("tag query = %v, want the seeded record", got)
	}
	assertErrorResponse(t, queryByTag(t, router, sequenceRepo, "missing"),
		http.StatusNotFound, codeNotFound, msgNotFound)
	assertErrorResponse(t, queryByDigest(t, router, sequenceRepo, testDigestB),
		http.StatusNotFound, codeNotFound, msgNotFound)
}

// TestStorageUnavailableStillValidatesInput closes the store and checks that
// validation happens before any storage access: illegal requests keep their
// 400 while legal ones degrade to 503 storage_unavailable.
func TestStorageUnavailableStillValidatesInput(t *testing.T) {
	path := filepath.Join(t.TempDir(), "service.db")
	st, err := store.Open(path)
	if err != nil {
		t.Fatalf("open: %v", err)
	}
	router := NewRouter(st)
	if recorder := postArtifact(t, router,
		registration(sequenceRepo, testDigestA, sequenceTag, true, regRetention, regSizeA)); recorder.Code != http.StatusCreated {
		t.Fatalf("seed register status = %d (%s)", recorder.Code, recorder.Body)
	}
	if err := st.Close(); err != nil {
		t.Fatalf("close store: %v", err)
	}

	// Invalid input is rejected with 400 even though the store is down.
	assertErrorResponse(t, postArtifact(t, router, registrationWithField("size_bytes", "null")),
		http.StatusBadRequest, codeInvalidInput, msgInvalidReg)
	assertErrorResponse(t, postArtifact(t, router, registrationWithField("signature_verified", "null")),
		http.StatusBadRequest, codeInvalidInput, msgInvalidReg)
	assertErrorResponse(t, getArtifacts(t, router, "repository="+sequenceRepo+"&tag="),
		http.StatusBadRequest, codeInvalidInput, msgInvalidQuery)
	assertErrorResponse(t, getArtifacts(t, router, "repository="+sequenceRepo+"&tag=&digest="),
		http.StatusBadRequest, codeInvalidInput, msgInvalidQuery)

	// Legal requests keep the published 503 degradation.
	assertErrorResponse(t, postArtifact(t, router,
		registration(sequenceRepo, testDigestB, sequenceTag, true, regRetention, regSizeB)),
		http.StatusServiceUnavailable, codeStorage, msgStorage)
	assertErrorResponse(t, queryList(t, router, sequenceRepo),
		http.StatusServiceUnavailable, codeStorage, msgStorage)
}
// TestRestartPreservesRecordsOrderAndPointers reopens the same database file
// and checks that immutable records, service-generated timestamps, list order
// and the current tag pointer all survive.
func TestRestartPreservesRecordsOrderAndPointers(t *testing.T) {
	path := filepath.Join(t.TempDir(), "service.db")

	st, err := store.Open(path)
	if err != nil {
		t.Fatalf("open: %v", err)
	}
	router := NewRouter(st)
	first := postArtifact(t, router, registration(sequenceRepo, testDigestA, sequenceTag, true, regRetention, regSizeA))
	pushedA := decodeBody(t, first)["pushed_at"].(string)
	second := postArtifact(t, router, registration(sequenceRepo, testDigestB, sequenceTag, true, regRetention, regSizeB))
	pushedB := decodeBody(t, second)["pushed_at"].(string)
	if err := st.Close(); err != nil {
		t.Fatalf("close before reopen: %v", err)
	}

	reopened, err := store.Open(path)
	if err != nil {
		t.Fatalf("reopen: %v", err)
	}
	t.Cleanup(func() { reopened.Close() })
	router = NewRouter(reopened)

	records := allRecords(t, queryList(t, router, sequenceRepo))
	if digests := recordDigests(records); len(digests) != 2 ||
		digests[0] != testDigestA || digests[1] != testDigestB {
		t.Fatalf("list after reopen = %v, want A then B", digests)
	}
	if records[0].(map[string]any)["pushed_at"] != pushedA ||
		records[1].(map[string]any)["pushed_at"] != pushedB {
		t.Fatalf("pushed_at values did not survive reopen: %v", records)
	}

	tagged := soleRecord(t, queryByTag(t, router, sequenceRepo, sequenceTag))
	if tagged["digest"] != testDigestB || tagged["pushed_at"] != pushedB {
		t.Fatalf("tag pointer did not survive reopen: %v", tagged)
	}
	expectStoredRecord(t, soleRecord(t, queryByDigest(t, router, sequenceRepo, testDigestA)),
		sequenceRepo, testDigestA, sequenceTag, true,
		float64(regRetention), float64(regSizeA), pushedA)
}

