263			"missing repository":   "tag=latest",
264			"blank repository":     "repository=%20%20",
265			"tag and digest":       "repository=team/app&tag=latest&digest=" + testDigestA,
266			"blank tag":            "repository=team/app&tag=%20",
267			"malformed digest":     "repository=team/app&digest=sha256:xyz",
268			"uppercase repository": "repository=TEAM/APP&tag=latest", // case-sensitive: valid but no match
269		} {
270			t.Run(name, func(t *testing.T) {
271				recorder := getArtifacts(t, router, query)
272				if name == "uppercase repository" {
273					if recorder.Code != http.StatusNotFound {
274						t.Fatalf("status = %d, want %d", recorder.Code, http.StatusNotFound)
275					}
276					return
277				}
278				if recorder.Code != http.StatusBadRequest {
279					t.Fatalf("status = %d, want %d (%s)", recorder.Code, http.StatusBadRequest, recorder.Body)
280				}
281				if code := errorCode(t, recorder); code != codeInvalidInput {
282					t.Fatalf("error code = %q, want %q", code, codeInvalidInput)
283				}
284			})
285		}
286	}
287	
288	func TestQueryNotFound(t *testing.T) {
