291	
292		for name, query := range map[string]string{
293			"unknown repository": "repository=other/repo",
294			"unknown tag":        "repository=team/app&tag=missing",
295			"unknown digest":     "repository=team/app&digest=" + testDigestB,
296		} {
297			t.Run(name, func(t *testing.T) {
298				recorder := getArtifacts(t, router, query)
299				if recorder.Code != http.StatusNotFound {
300					t.Fatalf("status = %d, want %d (%s)", recorder.Code, http.StatusNotFound, recorder.Body)
301				}
302				if code := errorCode(t, recorder); code != codeNotFound {
303					t.Fatalf("error code = %q, want %q", code, codeNotFound)
304				}
305			})
